SELECT a.root_type,g.account,a.account_name,CASE WHEN a.root_type='Income' THEN SUM(g.credit-g.debit) ELSE SUM(g.debit-g.credit) END AS amount FROM "tabGL Entry" g JOIN "tabAccount" a ON a.name=g.account WHERE (%(company)s='' OR g.company=%(company)s) AND (%(from_date)s='' OR g.posting_date>=%(from_date)s) AND (%(to_date)s='' OR g.posting_date<=%(to_date)s) AND a.root_type IN ('Income','Expense') GROUP BY a.root_type,g.account,a.account_name ORDER BY CASE a.root_type WHEN 'Income' THEN 1 ELSE 2 END,a.account_number
